import SwiftUI

/// The app icon, drawn in the app's own tokens.
///
/// It is a VIEW, rendered through the same preview harness as every other still,
/// for one reason: the design bible bans colour literals, and an icon generated by
/// a standalone script would fork the palette the moment a token moved. Rendering it
/// here means the icon is the same teal, the same near-black, the same reward pink
/// the Leads tab uses — by construction, not by matching hex codes.
///
/// WHAT IT SHOWS: the funnel this app exists to watch — leads scraped, leads
/// emailed, leads replied — as three descending bars. It is the same shape as the
/// breakdown panels inside the app, and it survives being 16 points wide, which a
/// line chart or a lettermark would not.
///
/// HIERARCHY (bible §1, §2): the identity hue leads — the widest bar is teal and
/// carries the one glow. The reply/reward pink is the ROLE colour and stays
/// demoted: smallest element, flat, no bloom. Two hues never split the hero layer.
struct AppIconArt: View {
    /// Apple's macOS icon grid: the artwork occupies 824 of a 1024 canvas, centred,
    /// leaving the margin the system expects — a full-bleed icon reads oversized
    /// next to every other app in the Dock.
    static let canvas: CGFloat = 1024
    static let plate: CGFloat = 824
    /// The continuous-curvature radius from the same grid (≈0.225 × plate).
    static let radius: CGFloat = 185

    /// Bar geometry as fractions of the plate, so changing `plate` can't silently
    /// break the margins.
    private static let barWidths: [CGFloat] = [0.665, 0.495, 0.325]
    private static let barHeight: CGFloat = 0.136
    private static let barGap: CGFloat = 0.092

    private static var plateRect: RoundedRectangle {
        RoundedRectangle(cornerRadius: Self.radius, style: .continuous)
    }

    var body: some View {
        ZStack {
            plateFill
            bars
        }
        .frame(width: Self.plate, height: Self.plate)
        // Clip the CONTENT to the plate, then draw the edge on top. The glow is
        // contained by arithmetic anyway (138pt of margin against a 30pt blur), but
        // clipping makes it contained by construction — a wider bar can't leak teal
        // fuzz outside the silhouette next to hard-edged icons.
        .clipShape(Self.plateRect)
        .overlay(
            // A top-lit edge so the plate reads as a surface, not a hole, on a light
            // desktop. Drawn after the clip so it isn't half-eaten by it.
            Self.plateRect.strokeBorder(LinearGradient(
                colors: [DesignTokens.borderHover, DesignTokens.borderDefault],
                startPoint: .top, endPoint: .bottom), lineWidth: 6)
        )
        // The one legitimate shadow: the plate genuinely floats above the desktop,
        // and Apple's own grid ships one. This is what the 100pt margin is for.
        .shadow(color: .black.opacity(0.45), radius: 26, y: 14)
        .frame(width: Self.canvas, height: Self.canvas)
        .background(Color.clear)
    }

    /// The world: near-black, faintly hue-tinted, lit from above (bible §5 — one
    /// overhead light source, expressed as a lightness step rather than a shadow).
    private var plateFill: some View {
        // Ends at `bgSurface`, NOT `bgRoot`. bgRoot is literally #000000, and a plate
        // that bottoms out at pure black dissolves into a dark desktop — the lower
        // half loses its silhouette entirely on a near-black wallpaper.
        LinearGradient(colors: [DesignTokens.bgElevated, DesignTokens.bgSurface],
                       startPoint: .top, endPoint: .bottom)
            .overlay(
                // The same teal wash the tab carries at its top edge.
                LinearGradient(colors: [DesignTokens.accent.opacity(0.14), .clear],
                               startPoint: .top, endPoint: .center)
            )
    }

    /// scraped → emailed → replied.
    ///
    /// CENTRED, not leading-aligned. Left-aligned descending bars put the ink
    /// centroid 6.5% left of the plate and left the lower-right quadrant empty — and
    /// once the top two teals blur together at small sizes, that silhouette is a
    /// letter F (or a text-align glyph), which is a system meaning this app does not
    /// have. Centred, the same three bars read as the funnel they are.
    private var bars: some View {
        VStack(alignment: .center, spacing: Self.plate * Self.barGap) {
            bar(fraction: Self.barWidths[0], color: DesignTokens.accent, glow: true)
            // Perceptual midpoint of the two: the middle step used to render DARKER
            // than the pink below it, so the funnel went loud → quiet → loud.
            bar(fraction: Self.barWidths[1], color: DesignTokens.accent.opacity(0.72), glow: false)
            // The reward role: smallest, flat, never glowing when the identity hue
            // isn't the one glowing.
            bar(fraction: Self.barWidths[2], color: DesignTokens.accentPink, glow: false)
        }
    }

    private func bar(fraction: CGFloat, color: Color, glow: Bool) -> some View {
        Capsule(style: .continuous)
            .fill(color)
            .frame(width: Self.plate * fraction, height: Self.plate * Self.barHeight)
            // The single bloom, on the identity hue only (bible §5: glow is reserved
            // for one moment; here it is the widest teal bar). Kept well under the
            // gap it has to clear — at radius 38 against a 56pt gap the bloom filled
            // the separator and the top two bars fused into one at 16px.
            .shadow(color: glow ? color.opacity(0.42) : .clear, radius: glow ? 30 : 0)
    }
}
